// Two processes: isolated — killing one can't touch the other.
// Process A's heap is not visible to Process B at all.
var worker = Process.Start("report-generator.exe");  // own memory space

// Two threads in ONE process: shared heap — fast, but racy.
int counter = 0;
void Bump() { for (int i = 0; i < 100_000; i++) counter++; }  // ❌ race

var t1 = new Thread(Bump); var t2 = new Thread(Bump);
t1.Start(); t2.Start(); t1.Join(); t2.Join();
// counter < 200_000: both threads read-modify-write the same field.

// ✅ Synchronize (or use thread-safe types):
Interlocked.Increment(ref counter);   // atomic
// or: lock, SemaphoreSlim, ConcurrentDictionary, channels…
